const lead = $('Unknown Results').item.json;
const raw = $input.item.json.status || 'unknown';

const statusMap = {
  safe:         'valid',
  role_account: 'valid',
  catch_all:    'catch-all',
  invalid:      'discard',
  disabled:     'discard',
  inbox_full:   'discard',
  disposable:   'discard',
  spamtrap:     'discard',
  unknown:      'discard'   // still unknown after retry → discard
};

return {
  json: {
    ...lead,
    validationProvider: 'reoon',
    validationRawStatus: raw,
    validationStatus: statusMap[raw] || 'discard'
  }
}

return $input.all().map(item => {                                                                                                                                   
  const { _summary, ...rest } = item.json;                                                                                                                          
  return { json: rest };                                                                                                                                            
});
